insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place, text_attribution, text_attribution_url)
values
(E'https://matcha-jp.com/tw/4173', E'zh-Hant', 1, E'【北海道】錯過3月櫻花不要緊！北海道追晚櫻人氣景點5選', E'趕不上3月份日本的櫻花季？3月無法放假來日本賞櫻？沒關係！就算日本本州櫻花季已經結束，北海道的櫻花才正要開始綻放！北海道位在日本最北方，櫻花綻放的日期也較東京、大阪等地晚一個月至一個半月，2026年預計於4月底5月初開始開花！Matcha小編精選了北海道五個人氣賞櫻景點，錯過本州櫻花季的讀者可考慮前來北海道賞櫻喔！\n\n是否錯過了三月份日本的櫻花季？或是三月無法放假來日本賞櫻？沒關係！就算本州的櫻花季已經結束了，北海道的櫻花才正要開始綻放呢！\n\n北海道是日本最北方的一個大島，由於緯度高的關係，有不同於本州的氣候及生態，櫻花綻放的日期也較東京、大阪等地晚一個月至一個半月。\n\n2026年預計於4月底5月初開始開花！Matcha小編精選了北海道五個人氣賞櫻景點，錯過本州櫻花季的讀者可考慮前來北海道賞櫻喔！', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/16-21450.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/16-21451.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/16-21444.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/16-21443.webp"]'::jsonb, E'2017-03-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/2830', E'zh-Hant', 1, E'迎接最早的浪漫紅葉! 5個北海道人氣賞楓景點', E'由於緯度高、天氣冷的關係, 北海道的楓葉是全日本最早變紅的, 最早大約9月上旬開始就陸續有樹葉開始轉紅, 小編精選5個賞紅葉絕佳景點, 可以依照自己的規劃及路線選擇適合旅程的紅葉景點, 想搶先一睹紅葉風采的人一定要跟Matcha小編來趟北海道紅葉之旅喔!\n\n到了秋天又是賞楓的季節, 有計畫去日本賞楓嗎? 由於緯度高、天氣冷的關係, 北海道的楓葉是全日本最早變紅的, 最早大約9月上旬開始就陸續有樹葉開始轉紅, 精選5個賞紅葉(※由於不只有楓葉, 還有許多不同植物的葉子也會轉紅, 因此在日本統稱「紅葉」, 以下通稱紅葉)絕佳景點, 可以依照自己的規劃及路線選擇適合旅程的紅葉景點, 想搶先一睹紅葉風采的人一定要跟Matcha小編來趟北海道紅葉之旅喔!\n\n全日本最早的紅葉從北海道大雪山開始, 每年9月上旬開始約一個月期間, 樹木從山頂漸漸往山下轉紅。從旭岳搭乘旭岳纜車前往「姿見」約10分鐘, 不僅可觀賞到全日本最早的紅葉, 還有豐富的高山植物生態及小動物可觀察。從「姿見」開始徒步5分鐘即達第一展望台, 這裡的景色開始可看到針葉林和闊葉林互相交錯生長, 旭岳被橘紅黃綠漸層的樹林妝點著非常美麗。\n\n札幌市內人氣紅葉景點之一, 搭乘纜車約15分至山頂。藻岩山除了紅葉外夜景也很有名, 被選定為「日本新三大夜景」, 白天可以賞美麗紅葉; 晚間可欣賞燦爛夜景, 此外山頂展望台有個「幸福之鐘」, 是情侶約會勝地呢! 利用藻岩山南側的付費「藻岩山觀光汽車道」也很推薦, 可以更深入藻岩山賞紅葉喔。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/11/22-132196.webp","https://resources.matcha-jp.com/resize/720x2000/2022/11/22-132197.webp","https://resources.matcha-jp.com/archive_files/tw/2016/09/13f99c05230c7834fe96a35ff46a4312_m.webp","https://resources.matcha-jp.com/resize/720x2000/2022/11/22-132198.webp"]'::jsonb, E'2017-10-18'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/1336', E'zh-Hant', 1, E'【2025最新】美到不想離開！北海道絕美紅葉景點10選', E'若是秋天要去北海道的話，那絕不能錯過以壯大自然為背景的紅葉美景！2025年北海道各景點的楓葉最佳觀賞期間約在10月〜11月上旬，本文推薦可以欣賞楓葉又能享受溫泉、戶外活動的北海道10大楓葉景點。\n\n北海道是位在日本最北端，最大的一個縣市。在豐富的自然環境中，有以新鮮海產為首的美味料理、讓人為之醉心的夜景等等魅力，不論是日本各地還是全世界，都有許多人到訪。\n\n若是要在秋天到訪北海道的話，那麼一定要欣賞一下在壯麗自然景色下造就出的楓紅景色了！ 本篇文章除了有介紹楓紅之外，也會介紹可以享受溫泉、戶外活動等等北海道的10個人氣賞楓景點和往年的楓紅時期。\n\n由於北海道的範圍相當廣，依據場所不同，楓紅時期雖然有差異，但北海道大多景點的楓葉觀賞期間落在9月中旬〜11月上旬開始能賞楓葉。其中層雲峽的楓紅在日本境內可說是最早開始，大約在8月下旬左右就開始了。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/10/11-130686.webp","https://resources.matcha-jp.com/resize/720x2000/2022/10/11-130685.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58210.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58208.webp"]'::jsonb, E'2018-10-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/4255', E'zh-Hant', 2, E'弘前城', E'弘前城（日語：弘前城／ひろさきじょう，羅馬化：Hirosaki-jō）是位於日本青森縣弘前市的一座城堡，別名鷹岡城、高岡城。\n\n弘前城的天守、櫓修建於江戶時代且保存至今，是日本的重要文化財。弘前城全體也是日本國家指定的史跡之一。在江戶時代，弘前城是弘前藩津輕氏4萬7千石的居城和弘前藩的藩廳，也是津輕地方的政治經濟中心。\n\n弘前城位於津輕平原，是一座由本丸、二之丸、三之丸、四之丸、北之郭、西之郭六個部分組成的梯郭式平山城。弘前城興建之初東西寬612米，南北長947米，總面積達385,200平方米。\n\n現在弘前城的護城河、石牆、土壘等城郭整體仍保持廢城時的原型，有8棟江戶時代的建築得以現存，其中天守是12座現存天守之一。弘前城的現存建築均是日本的重要文化財。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/01/07-94518.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/07-94519.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/28-175574.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/28-175575.webp"]'::jsonb, E'2017-04-03'::timestamptz, E'弘前城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%BC%98%E5%89%8D%E5%9F%8E'),
(E'https://matcha-jp.com/tw/24040', E'zh-Hant', 2, E'【2026】7個青森櫻花名所推薦！粉嫩櫻花看到飽', E'青森縣內有多處著名的櫻花名所，你是否也在煩惱該去哪裡賞花呢？在這篇文章中，為您精選了青森縣7個櫻花名所。如果您計畫在青森縣賞櫻，請務必參考本篇文章，規劃屬於您的花見行程吧！\n\n青森縣位於東北地方，是一個自然資源豐富的縣，擁有如世界遺產白神山地這般美麗自然景觀，並且面向大海。\n\n在這樣的青森縣，每到春天便有許多適合賞櫻的景點。如果您計畫在春季造訪青森，或是住在青森的人，肯定想知道有哪些推薦的賞櫻名所吧？\n\n因此，這篇文章將為您介紹青森縣7個能盡情享受櫻花的名所。我們將詳細介紹每個景點的特色以及櫻花的最佳觀賞時間，請務必參考本篇文章，規劃一趟春季的賞櫻之旅！', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223787.webp","https://resources.matcha-jp.com/resize/720x2000/2026/05/14-264026.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223788.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/28-175575.webp"]'::jsonb, E'2025-03-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23594', E'zh-Hant', 2, E'弘前公園', E'弘前公園（日語：弘前公園／ひろさきこうえん）是位於日本青森縣弘前市的一座公園，又稱鷹揚公園、鷹揚園。弘前公園種植有約50種2600株櫻花，是日本著名的賞櫻勝地。\n\n弘前公園被選入日本都市公園100選、日本歷史公園100選、日本櫻名所100選。擁有現存天守的弘前城也位於弘前公園內。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/13-218800.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/07-94518.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/05-200610.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/13-218801.webp"]'::jsonb, E'2025-01-12'::timestamptz, E'弘前公園', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%BC%98%E5%89%8D%E5%85%AC%E5%9C%92'),
(E'https://matcha-jp.com/tw/22576', E'zh-Hant', 3, E'岩手縣警察', E'岩手縣警察（日語：岩手県警察／いわてけんけいさつ，羅馬化：Iwate ken keisatsu）是日本岩手縣的警察機關，由岩手縣政府下設的岩手縣公安委員會管轄。\n\n至2025年，岩手縣警察設有16個警察署，警官總數2,472人。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/14-209310.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/09-208235.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/05-200599.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/05-207557.webp"]'::jsonb, E'2024-11-09'::timestamptz, E'岩手縣警察', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%B2%A9%E6%89%8B%E7%B8%A3%E8%AD%A6%E5%AF%9F'),
(E'https://matcha-jp.com/tw/15704', E'zh-Hant', 2, E'美味的海鮮寶庫！推薦日本東北和關東的19種水產加工品美食', E'日本的東北和關東的太平洋沿岸地區以世界知名的漁場而聞名。本文將精選介紹這些地區所採捕的干貝、魷魚、鯖魚等水產食材所製作的絕品水產加工品美食共19款！\n\n特別是岩手縣、宮城縣和靠近這些地方的青森縣，面向三陸沖和金華山沖，產出了肥美的海產，這些美味的水產加工品被運送到日本各地和海外。三陸和金華山地區是北方的親潮和南方的黑潮交匯之處，各種魚類聚集於此，因此被譽為世界三大漁場之一。\n\n此外，靠近東京的關東地區的千葉縣以日本有名的沙丁魚漁獲量自豪，茨城縣有眾多優良的漁場，很多伊勢龍蝦、鯖魚、沙丁魚等水產類商品也在這裡捕撈上岸。 本文將紹介在擁有豐富海鮮的東北和關東地區,特別受到矚目的水產加工品美食，並按縣別進行介紹！\n\n提到津輕海峽的品牌海產，不得不提的就是因受冷海水和強勁洋流的培育而成的「海峽鮭魚」。養殖這種魚難度極高，甚至需要長達30年才能穩定養殖，但現在已成為青森代表的品牌。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/11/15-152416.webp","https://resources.matcha-jp.com/resize/720x2000/2022/08/01-128818.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/05-119338.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/17-110892.webp"]'::jsonb, E'2023-12-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7375', E'zh-Hant', 3, E'【2026】嚴選岩手縣景點15個！不只有盛岡，還有平泉世界遺產！', E'岩手縣是面積日本僅次於北海道的第二大縣，擁有豐富的山川海景，還是日本民俗學者柳田國男探索民間故事的靈感之地，甚至是著名童話作家宮澤賢治的故鄉。那麼該怎麼玩遍岩手縣呢？本文將會深入介紹岩手景點、美食、交通等資訊，快跟著我們的腳步來暢遊岩手縣吧！\n\n岩手縣位於日本東北地區，擁有美麗的自然景觀，面積僅次於北海道，西靠奧羽山脈，東臨太平洋。這裡以12世紀奧州藤原氏的歷史遺跡聞名，並且是著名民俗學者柳田國男研究民間故事的舞台。\n\n此外，岩手也是著名童話作家宮澤賢治的故鄉，他將這片美麗的土地稱為「理想鄉」。本文將會介紹各式各樣的岩手資訊，如岩井景點、交通、美食等。\n\n盛岡地區位於岩手縣西北地區，為江戶時代熱鬧的城下町，現在仍是岩手縣的縣政府所在地，岩手縣最熱鬧的地方，有盛岡城跡與岩手銀行紅磚館等具歷史性的觀光景點。 小編推薦延伸閱讀 岩手縣「盛岡市」旅遊攻略！遊走充滿文學氣息與在地美食的城市 岩手縣', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/20-77272.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/20-77273.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/18-77210.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/05-207557.webp"]'::jsonb, E'2019-06-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/11280', E'zh-Hant', 3, E'【岩手】搭三陸鐵道遊港都！感受熱血水產王子與絕景的魅力', E'不少人是從《小海女》認識三陸鐵道這條沿途碧海藍天、與壯麗奇岩景觀相伴的鐵路。而三陸鐵道的公司所在地「宮古」，除了因這片特殊海岸地形擁有多處自然絕景如青之洞窟以外，也以豐富的漁獲蘊藏量被譽為世界三大漁場之一，加上當地名人魷魚王子的熱血宣傳，讓水產加工產品的美味與魅力發揚光大。\n\n在2013年播出，成為知名日劇的《小海女》至今依舊深受歡迎。而在劇中出現的岩手縣「三陸鐵道谷灣線」鐵路，其本公司就位在宮古。鐵道名稱便是以岩手的三陸谷灣命名。\n\n311東日本大地震時「三陸鐵道」受到海嘯侵襲而嚴重損壞，經過3年後在2014年3月全線修復完工，卻又在2019年受到颱風重創，歷經不少的試煉，總算在2020年恢復全線通車。\n\n三陸鐵道谷灣線沿途行駛三陸海岸，不時能從窗外眺望壯麗的海景，更是串連著各城市的交通動脈，對於當地居民和鐵道迷來說，都是一條極為重要的鐵道。 三陸鐵道宮古站', E'["https://resources.matcha-jp.com/resize/720x2000/2022/07/24-128578.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/24-128579.webp","https://resources.matcha-jp.com/resize/720x2000/2022/08/17-129053.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/24-128582.webp"]'::jsonb, E'2022-07-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/9716', E'zh-Hant', 4, E'【仙台】初遊仙台、松島必去景點與必吃美食的兩天一夜推薦路線', E'本篇介紹東北地方的人氣觀光地、環遊仙台和松島的兩天一夜推薦旅遊行程。從歷史建築到美味的日式甜點等地域獨有人氣美食，以及初次造訪者不容錯過的必看景點！請參考該示範路線，好好計劃一趟旅程吧。\n\n東北地方的交通要地是仙台。它是一處熱門的觀光地，既有戰國武將伊達政宗的相關史跡，也有可口美食。另外，距離仙台市30分左右電車距離的松島也是東北地方的必遊觀光地之一。\n\n本文針對初次造訪的遊客，介紹以仙台為據點，環遊經典景點的兩天一夜示範路線。第1日巡遊仙台、第2日則移步到以景色優美著稱的松島！\n\n在仙台市內出發可選擇JR、地鐵、巴士等3種交通工具。如為1日遊，建議選擇仙台觀光環城巴士「Loople仙台」的1日乘車券。成人630日圓即可自由乘降，另外，出示乘車券即可享受仙台城資料館、餐廳、伊達政宗靈廟瑞鳳殿的門票折扣！', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/23-102002.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/23-101966.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/24-102031.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/24-102032.webp"]'::jsonb, E'2020-05-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/25652', E'zh-Hant', 4, E'【仙台】仙台逛街首選！「MITSUI OUTLET PARK 仙台港」逛街、美食、摩天輪一次滿足！', E'東北第一大的購物聖地「MITSUI OUTLET PARK 仙台港」，匯聚超過100個人氣品牌，能盡情享受購物樂趣。除了購物，園區附近還有其他景點，如「仙台海之森水族館」，以及被譽為日本三景的名勝「松島」。此外，還能搭乘仙台港地標「港之花摩天輪」俯瞰仙台市區與港灣美景。\n\n位於仙台港邊的「MITSUI OUTLET PARK 仙台港」是東北第一大的購物聖地，集結超過100個人氣品牌，時尚、運動、生活雜貨一應俱全。園區周邊也有許多適合觀光的推薦景點，像是適合親子同遊的「仙台海之森林水族館」；或是從鄰近的「中野榮站」出發，搭電車約19分鐘即可抵達有日本三景之稱的名勝「松島」，在行程上的安排便利又充實。\n\n另外，搭乘園區廣場的地標「港之花摩天輪」，則可將仙台市區與港灣景色盡收眼底，購物、觀光、娛樂一次滿足。\n\n前往「MITSUI OUTLET PARK 仙台港」，可搭乘電車，也能利用市區巴士直達。另設有大型停車場，對自駕旅客同樣友好，是購物與觀光的理想地點。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/08-243682.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/24-242140.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242771.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/24-242142.webp"]'::jsonb, E'2025-08-24'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23552', E'zh-Hant', 4, E'【2026】介紹仙台8大賞櫻景點！包含郊外容易賞櫻的知名地點', E'仙台市內櫻花名勝眾多。本文將為您介紹代表仙台市的6大賞櫻景點，包括西公園和錦町公園等。此外，我們還會介紹2個仙台市郊外的賞櫻景點，如白石川堤一目千本櫻和西行戻松公園，在這裡您可以欣賞到令人嘆為觀止的櫻花大道。希望這些介紹能為您提供參考。\n\n「森之都」之稱的仙台被大量綠意環繞。這樣的仙台也充滿了賞櫻名勝。因此，在2025年的賞花季節，可能有許多人考慮在觀光之餘順道在仙台賞櫻。\n\n這次我們將介紹代表仙台市的6個賞花景點，包括西公園和錦町公園等。我們還會介紹距離仙台市不遠的郊外賞花景點，如白石川堤一目千本櫻和西行戻松公園等壯觀的櫻花林，請大家參考。\n\n根據日本氣象權威網站的預測，2026年仙台的櫻花預計於 4 月 6 日左右開花，並於 4 月 11 日左右達到滿開。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/14-219106.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/14-219107.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/14-219108.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/14-219109.webp"]'::jsonb, E'2025-02-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/9532', E'zh-Hant', 5, E'【Ready For Japan! Vol. 2】喜淚交織的感動！日本觀光影片10選', E'在為下次旅行計劃考慮時，大家免不了會想參考一下觀光影片。日本多個地區錄製了能飽覽優美絕景、令人莞爾的視頻。MATCHA編輯挑選了10則獨特的觀光影片，在此為大家介紹。\n\n近年來，日本各地方政府和企業製作了許多觀光影片發布在YouTube網站上。其中，有不少令人不禁莞爾又或感動的作品。\n\n於疫情逐漸升溫之下，各位於短期間想必已無法踏上日本。這時，不如在家先看看各地推出的觀光影片解解渴、過過乾癮吧！為下次的日本旅行描畫一下理想草圖，懷抱一點期待與希望吧！\n\n為此，請看看MATCHA編輯部推出的連載「Ready For Japan! vol.2」，本文收集了令人感動得喜淚交織的日本觀光影片，精彩內容別錯過囉。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99413.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99414.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99415.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99416.webp"]'::jsonb, E'2020-03-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7661', E'zh-Hant', 5, E'【2026】秋田自由行最新攻略！景點、交通、美食、伴手禮、祭典、模範行程', E'來到日本秋田就可體驗與療癒的秋田犬互動，體驗在雪中泡溫泉的樂趣，還能品嚐道地美食的秋田米棒鍋！本篇將會分享秋田交通、景點、美食伴手禮及推薦一日遊行程等資訊，讓各位在短時間內更了解充滿魅力的秋田縣！\n\n此外，如果有看過著名的電影「忠犬小八」應該都對電影裡可愛的秋田犬小八有印象吧！那部電影讓許多人認識到秋田犬的忠誠之心，也因為秋田犬知名度的提升，許多旅客來到這裡就是為了與超萌秋田犬拍照互動。\n\n而喜歡溫泉的人，也可以到秋田溫泉勝地「乳頭溫泉」，享受在雪白的景色中泡湯的樂趣喔！\n\n如果是計畫夏天來秋田的話，非常推薦將行程規劃在8月初。因為「秋田竿燈祭」會舉辦在每年的8月3日至6日，來自各地的旅客能夠看到約10,000個竿燈同時搖曳在夜空中的景象。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/04/21-177659.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/18-177409.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/18-177411.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/18-177413.webp"]'::jsonb, E'2019-09-27'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3856', E'zh-Hant', 5, E'秋田冬季必訪！「橫手雪祭」完全攻略：雪洞體驗、梵天奉納與交通住宿', E'橫手雪祭每年冬季在秋田橫手市舉辦，市區遍布傳統雪洞與夢幻蠟燭光海，還可參加預約制雪洞體驗與迷你雪洞製作。祭典重頭戲為有300年歷史的「梵天（ぼんでん）」奉納，壯丁抬著五公尺長道具奔赴旭岡山神社場面壯觀。還有整理會場、巡迴巴士、從橫手站步行資訊與防寒、靴子建議，方便行前準備。\n\n本篇將介紹到秋田縣橫手市的「横手雪祭」，在横手雪祭時到處都可以看到「雪洞」及蠟燭心，宛如異想世界一般。還可以看到擁有300年歷史的奉納活動，想要體驗日本雪國的人，一定要來一探究竟。\n\n「橫手雪祭」於每年1月至2月會舉辦在東北地方的秋田縣橫手市。不僅可以體驗日本叫做「かまくら(ka ma ku ra)」的雪洞，還可以看到日文叫做「ぼんでん( bon den )」大型納奉神祭用具的一連串活動，這是一個很壯大的民俗慶典。\n\n雪洞「かまくら」據說是自450年前於日本降雪地區，在小正月(※1)時會用來祭祀水神的儀式。進入雪洞裡面，將銅板投入錢箱祭祀水神，據說可以祈求家内安全、商業興隆、五穀豐收等心願。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/13-13718.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/13-13716.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/13-13717.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/13-13719.webp"]'::jsonb, E'2018-02-27'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24227', E'zh-Hant', 6, E'【2026】山形賞櫻花見名所10選！開花時期與秘境景點推薦', E'根據2026年山形櫻花的開花預測，為您介紹從經典名所到隱藏秘境的賞櫻地點。計劃在山形進行賞櫻觀光時，請務必參考開花預測，選擇最佳花期前往，以便盡情享受美麗的櫻花！\n\n此外，西藏王的大山櫻以及倉津川垂枝櫻等，如獨立的一株櫻花樹或順著河川綿延成景的櫻花林，都展現了各地區獨特的風貌。因地形高低落差大，開花時期分布較長，可以享受長時間的賞花樂趣。\n\n本篇文章將提供山形櫻花的開花預測，並精選出10個櫻花名所，讓您探索山形的櫻花魅力。\n\n園內保留了日本最古老的木造六角燈塔，還有北前船的模型等設施，讓來訪者能夠一邊欣賞櫻花，一邊體驗歷史的風情。此處的櫻花花期一般在4月中旬至下旬，主要為染井吉野櫻和垂枝櫻。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/22-225527.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/22-225502.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/22-225505.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/22-225517.webp"]'::jsonb, E'2025-03-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/20762', E'zh-Hant', 6, E'【山形】賞楓景點5選 ：一次捕捉絕美山谷＆乘船遊秋楓的限定景緻', E'若喜歡靜謐賞楓之旅，在地小編推薦造訪東北山形，包括距從山形車站徒步可抵達的紅葉公園、可俯瞰絕美山谷的山寺、搭船遊最上川等，本文將介紹5個新手老手都會愛上的楓葉景點。\n\n說到日本旅行就不要錯過的楓葉季節，這次想介紹山形的楓葉景點，山形縣位於日本東北地方的南邊，南邊有福島，東邊則緊鄰宮城，不管是電車或者巴士甚至選擇自駕，想來東北賞楓也不要錯過交通便捷的山形，只搭乘大眾運輸的旅人也可以來一趟放鬆的山形秋楓之旅，另外在地小編也選了自駕賞楓的景點！\n\n位於山形市區住宅區內的日式公園，從山形車站步行約３０分鐘。追朔歷史這邊最早是一座寺廟名為宝幢寺庭的寺院，在被山形市收購作為都市公園，整理修復之後，其中園內也作為一部分為當地公民館別名為「清風莊」也有茶室「寶紅庵」，可以說是市內少有的日式庭院公園。每到秋天紅葉時期也不定期舉辦市民茶會，地腹雖然不大，但在山形市區裡更顯得別緻，在市民有著山形小京都的稱號，是一座是市內靜謐的日式楓葉小景點。 紅葉公園\n\n來山形讀者也不陌生的山寺，全名為「寶珠山立石寺」，是山形縣內重要的信仰地之一，秋高氣爽季節裡也非常適合登上山寺，從山形車站搭乘仙山線電車約２５分左右即可抵達。一下車讀者可以先欣賞山寺特有的山面岩壁仔細一看還可以發現木造修行建物，十分壯觀。山寺是縣內有名的修行場所，入山參拜費需要支付３００日圓，需爬行１０１５段階梯，傳說爬完之後就能消除煩惱，努力後最大的收穫就是在「五大堂」俯瞰山谷間的山寺區域，這個景色不管是秋天來訪或各個天氣都有不同氛圍，是筆者喜歡山寺的其中一個原因。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/30-190496.webp","https://place.matcha-jp.com/2022/12/23-10-19-03-3cdd9f041640026ad698b648dc0c7b99.jpg","https://resources.matcha-jp.com/resize/720x2000/2024/08/16-192713.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/16-192719.webp"]'::jsonb, E'2024-07-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7877', E'zh-Hant', 6, E'「山形」賞櫻景點5選！一次解鎖逛祭典、遊城跡、泡溫泉的旅遊成就！', E'每年的四月中旬至下旬為山形縣的賞櫻旺季，對於時間寶貴的訪日遊客來說，想要在櫻花綻放的短暫黃金時間之內，一邊賞櫻一邊解鎖逛祭典、參拜神社、暢遊城跡、大啖美食、泡溫泉等等的旅遊成就並非易事。不過別擔心，本次小編就要嚴選5處山形賞櫻聖地來幫大家輕鬆達成造訪日本的各種旅遊心願！\n\n如果你是個貪心擁有邊賞花邊享受文化體驗、邊賞花邊賞城、邊賞花邊泡溫泉、邊賞櫻邊吃日本美食等等心願的旅客，這篇文章包準可以幫你一次達成！\n\n根據日本氣象權威網站的預測，2026年山形的櫻花預計於 4 月 10 日左右開花，並於 4 月 14 日左右達到滿開。\n\n來米澤除了賞櫻的樂趣之外，千萬不可以錯過品嚐米澤的道地美食米澤牛料理，無論是米澤牛涮涮鍋、米澤牛牛排、米澤牛壽喜燒等料理，都可以用非常優惠的價格來放肆品嚐，有興趣的人可以參考此篇米澤牛美食文章。 松が岬公園', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/04-85223.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/04-85205.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/04-85207.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/04-85208.webp"]'::jsonb, E'2019-09-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24217', E'zh-Hant', 7, E'三春瀧櫻', E'三春瀧櫻（英語：みはるたきざくら）是位於日本福島縣田村郡三春町的一株紅枝垂櫻，其樹齡超過1000年。三春瀧櫻被列入天然紀念物，是福島縣著名的觀光景點之一。\n\n三春瀧櫻也是日本五大櫻和三大巨櫻之一，花季參觀時需要付費。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225359.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225360.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225361.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225362.webp"]'::jsonb, E'2025-03-06'::timestamptz, E'三春瀧櫻', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E4%B8%89%E6%98%A5%E7%80%A7%E6%AB%BB'),
(E'https://matcha-jp.com/tw/23836', E'zh-Hant', 7, E'【2025】福島縣賞櫻景點10選！還有舉辦櫻花祭的景點', E'福島縣分布著許多日本國內首屈一指的櫻花名勝。然而，對於縣外的人來說，可能很多人並不知道福島有哪些櫻花名勝。因此，這次我們將介紹從經典櫻花名勝到隱藏景點的福島櫻花景點10選。\n\n然而，媒體爭相報導的往往是目黑川或弘前公園等所謂的知名地點。福島縣以外的人可能有許多不太了解福島有哪些櫻花名勝。\n\n花見山是園主基於「希望能撫慰人們的心靈」的想法，於1959年開放的公園。被已故攝影師秋山庄太郎先生讚譽為「福島的桃花源」的花卉名勝，如今吸引了來自全國各地的眾多遊客。\n\n園內到了春天，梅花、連翹、東海櫻、木瓜、吉野櫻、觀賞桃等約70種花卉一齊盛開。百花齊放，將整座山包裹在淡粉色中。遠眺吾妻連峰與花朵的對比令人歎為觀止。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221833.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221835.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221839.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/31-221844.webp"]'::jsonb, E'2025-02-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/22494', E'zh-Hant', 7, E'福島縣美食7選！從當地名物到B級美食詳細介紹', E'本文將為您介紹7種在福島值得品嚐的推薦美食。從能讓身體暖和起來的安康魚鍋到喜多方拉麵，以及美味的炸豬排蓋飯等，盡是福島獨特的美味。如果您計劃訪問福島，請務必參考這篇文章。\n\n本文將為您介紹從福島縣的當地特產到著名的B級美食。訪問福島時，請務必品嚐這些美食。\n\n福島縣的「元祖圓盤餃子 滿腹」是一家誕生於昭和30年代的福島市名店餃子店。起源於1953年，菅野かつゑ女士在路邊攤賣起圓盤餃子。她將在滿洲學到的煎餃技術帶回故鄉經營，豐盛的口味贏得了人氣。\n\n孫女椎野仁子女士繼承了這個傳統，從餃子皮開始手工製作，一個一個包好，然後在與七輪相配的26公分平底鍋上一次煎30個。採用獨特的方法先煎出金黃色後再蒸煮，讓顧客可以享受到香脆又滑嫩的餃子口感。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/08-208208.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/08-208210.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/08-208211.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/08-208212.webp"]'::jsonb, E'2024-11-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/12737', E'zh-Hant', 8, E'在茨城縣境町來一趟隈研吾的現代建築之旅吧！大師的設計．監修的建築6選', E'為了振興地方及促進發展，茨城縣的境町在推動各種企劃案下，請來了建築大師隈研吾來設計與監修町內的建築，如今已擁有7處隈研吾建築的境町變身為隈研吾新聖地。進行建築巡禮的同時不妨將體驗當地美食及鑑賞藝術等加入行程，讓這趟巡禮不止於欣賞建築，更是個認識地方城鎮的好機會。\n\n境町位於茨城縣西邊，自古以來因利根川流經，古時是作為物流匯聚之地興盛；近年來則是因建築大師隈研吾於此設計監修了數座建築，備受矚目，從2018年起，短短4年多便完成了6處建築，使境町有了「隈研吾建築聖地」之稱。本記事就要跟各位介紹這6棟建築物。\n\n位於利根川畔、國道旁的「道之驛 境」以舊時倉庫意象了復原了白牆黑瓦的建築風格，設有特產館，販賣的都是能代表當地的新鮮食材及加工食品，這裡更兼具了觀光案內所的功能，提供靠站遊客關於境町一帶的情報，也藉此宣傳當地的魅力與特色。\n\n隈研吾所設計的「茶藏」在2014年4月落成於「道之驛 境」的北側，不僅成了當地的地標之一、也替境町增添不少話題。外觀如翅膀般層層疊起的木板是以倉庫屋頂為意象，使用了縣產的杉木材；內部挑高的構造配上垂弧優雅的布簾及照明，布幕深淺不一帶漸層的綠色，是用茶葉色素染上的，在設計上完美地結合了傳統意義與現代文化，作為新建築物實屬當之無愧。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/09/01-144925.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/01-144926.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/02-144941.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/01-144927.webp"]'::jsonb, E'2023-09-01'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/25326', E'zh-Hant', 8, E'【關東地區】秋天到了～一起來賞掃帚草吧！4個超人氣推薦景點🍁', E'秋季，是最適合出遊的時節之一。天氣涼爽不冷、空氣清澈宜人，是賞楓、拍照、走訪名勝的最佳時機。群山漸染紅黃，無論是親近自然還是探訪人氣景點，都能感受到秋天的魅力。\n\n秋季，一個擁有豐富多彩享受方式的季節。氣溫漸進，空氣更清新，正是郊遊散步的好時節。山脈變幻色彩，自然之美被認為是一年中最令人心馳神往的季節。\n\n秋天裡一定不能錯過的一種植物是「掃帚草」，日文中被稱為「ほうき草（hokigusa）」或「コキア」。這是一年生植物，春夏呈現翠綠色，到了秋天則轉變為鮮紅色，形成壯觀的紅葉景觀。\n\n這種植物的最大特徵是其蓬鬆圓潤的外形，模樣可愛，深受喜愛。鮮綠色在夏天給人一種清涼的感覺，而到了秋天，葉子會變成紅色和橙色，形成一片美麗的紅色地毯。這種季節變化正是掃帚草最大的魅力！', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238066.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238089.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238068.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238069.webp"]'::jsonb, E'2025-07-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/12698', E'zh-Hant', 8, E'【東京近郊】日本第2大湖「霞浦」的推薦戶外活動與美食', E'距離東京只要大約1小時即可抵達的茨城縣霞浦，為日本面積第2大的湖泊。這裡能捕撈到各式各樣的漁獲，自古便加工成佃煮以保存食用。本文將同時介紹佃煮的魅力，以及霞浦一帶的好玩活動與觀光勝地。\n\n位在茨城縣東南部的「霞浦」，是日本面積第2大的湖泊，湖岸一周長達252公里。從東京只要約1小時即可抵達，是關東地區的人氣觀光地。\n\n霞浦周邊有許多可以徜徉在超美景色中的戶外活動，像是可以搭船參觀航行在湖面的「帆引船」，或是在湖邊騎單車鐵馬遊等，各種這裡才有的體驗活動，琳琅滿目十分精采。\n\n而且霞浦為淡水湖，盛產公魚及白魚、淡水蝦等種類多元的魚類，當地也很多水產加工業者，可以找到這裡才有的好吃美食喔。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144617.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144613.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144606.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144614.webp"]'::jsonb, E'2023-10-11'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/8117', E'zh-Hant', 9, E'【栃木】奧日光健行全攻略：從湯之湖到華嚴瀑布，感受最自然的日光之美', E'想深度體驗日光嗎？除了世界遺產，奧日光的自然美景更不容錯過！本篇為您規劃從湯之湖、湯瀧瀑布、戰場之原到華嚴瀑布的經典健行路線。最新日光國立公園慢活旅行指南，帶您遠離喧囂，徹底洗滌心靈。\n\n身為世界文化遺產的日光社寺群固然有名，但若想體會日光最自然的靈魂，絕對要前往「奧日光」。搭上巴士深入日光深處，從湯元溫泉出發，一路上有碧綠湖水、蒼鬱森林、高聳瀑布與廣大濕地，完全拋開都市喧囂，領略日光國立公園的雄大與寂靜。\n\n從日光車站搭乘前往湯元溫泉的巴士，約 1 小時 20 分鐘即可抵達湯之湖。這裡是奧日光健行的絕佳起點，湖畔環境清幽，不少釣魚愛好者會在此享受垂釣樂趣。\n\n沿著湖水西側步道向南前進，便能前往「湯瀧瀑布」。沿途樹影搖曳，湖水聲伴隨腳步聲，相當迷人。提醒您，部分路段為泥土路，建議穿著舒適的運動鞋前往。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/10/15-88247.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/15-88248.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/15-88249.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/15-88250.webp"]'::jsonb, E'2019-10-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3803', E'zh-Hant', 9, E'【栃木】宇都宮半日旅：使用「大谷観光一日乗車券」探訪神劍闖江湖拍攝地', E'想要體驗別人沒有沒有玩過的東京近郊文化之旅的話，就買張「大谷観光一日乗車券」，輕鬆暢遊美味「宇都宮」和文化氣息十足的「大谷」。本篇先針對大谷地區如何安排半日遊，以及神劍闖江湖拍攝地等相關景點進行介紹。\n\n開拓日本絕景的採訪團隊，這次要將一處隱藏在地底下的礦場遺跡公開於大家眼前，此處佔地高達2萬平方公尺，就有如一個東京巨蛋大小。在昏黃燈光打光下，整體散發出如古代羅馬遺跡般的夢幻氛圍，而且更令人震驚的是，這樣的奇幻石之都不用千里迢迢到國外欣賞，就在日本！在這之前先來搞定交通方式吧！\n\n想要體驗別人沒有沒有玩過的東京近郊文化之旅的話，就跟著小編的步伐、買張「大谷観光一日乗車券」，輕鬆暢遊美味「宇都宮」和有如古羅馬氛圍的「大谷」。\n\n若你不懂日文，或是首次嘗試東京近郊自由行的遊客，有一張包含公車車票、參觀處入場券的一日券，真得可以省去許多旅遊行程上的麻煩。而由宇都宮所推出的大谷観光一日乗車券（一張2000日元）就是一張大大超值的票券。 主要是因為不用精算上下公車要花多少錢，而且此一日券大方送地涵括大谷資料館入場券（800日元）、大谷寺參拜券（500日元），還有宇都宮與大谷地區中共8處設施的優惠券，不僅省去買票麻煩，還一個人就能省下至少400日元的旅費，超級划算。', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/29-12790.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/29-12791.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/29-12793.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/29-12792.webp"]'::jsonb, E'2017-01-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/21527', E'zh-Hant', 9, E'【日光】除了東照宮，別忘了造訪絕美賞楓景點12選', E'在日光，壯觀的秋色與世界遺產的建築相融合，成為東京近郊最佳的秋季旅遊目的地之一。我們介紹12個擁有壯麗紅葉的地點，從中禪寺湖和華嚴瀑布到日光東照宮。\n\n日光 一直是許多日本歷史名人的歷史避難所。從東京搭乘火車僅需兩小時，日光是短途旅行的理想地點，特別是在秋季，充滿壯麗的自然美景！\n\n由於海拔較高，中禪寺湖和華嚴瀑布一帶的紅葉最早可在十月中旬至十月底時出現。日光的世界遺產地區則可以在十一月初至中旬享受到美麗的紅葉。\n\n華嚴瀑布四季皆美，尤其在秋天，周圍的森林化身為紅、橙、金色的燦爛景象，真的如夢似幻。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/11-196845.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/09-196365.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/16-197665.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/14-197482.webp"]'::jsonb, E'2024-09-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24263', E'zh-Hant', 10, E'【2026】群馬櫻花名所10選！賞花最佳時期、夜櫻與點燈資訊大公開', E'群馬縣擁有許多著名的櫻花景點。本文將為您介紹「赤城南面千本櫻」、「櫻山公園」、「高崎城址公園」等可以享受夜櫻與櫻花祭的賞花地點，同時提供開花時間、最佳觀賞時期及燈光點綴等實用資訊。\n\n比如在前橋市內，預計2026年為3月下旬(前橋公園約3月26日左右)開花，並於4月上旬(4月初)迎來滿開。高崎與伊勢崎等縣南地區也在4月初進入花期。\n\n另一方面，北部及山間地區的開花時間稍晚。標高較高的地區(如沼田市或水上溫泉周邊地區)的櫻花最佳觀賞期為4月中旬到下旬，甚至可以延續到黃金周期間。\n\n群馬縣南北幅員廣闊，各地區櫻花的觀賞時間有所不同，建議確認想造訪地區的櫻花花期。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226110.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226111.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226112.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226113.webp"]'::jsonb, E'2025-03-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/22991', E'zh-Hant', 10, E'群馬高山秘境！攻略天空中的溫泉鄉「萬座溫泉」', E'位於群馬縣嬬戀村的萬座高原的「萬座溫泉」，坐落於1800公尺的高山之中，被稱為「天空中的溫泉鄉」。這裡的溫泉水源豐富，日湧540萬公升，主要是高濃度的硫磺泉，據說對皮膚疾病和關節痛等有療效。\n\n萬座溫泉位於群馬縣嬬戀村，是日本最知名的高海拔溫泉之一，坐落於標高1,800公尺的嬬戀高原。\n\n溫泉的泉質屬於強酸性硫磺泉，水溫平均約80度，帶有乳白色的特徵，對皮膚和身體健康具有很高的療效。\n\n溫泉的泉質屬於強酸性硫磺泉，水溫平均約80度，溫泉水呈乳白色，散發出淡淡的硫磺氣味，硫磺泉以其對皮膚和身體的療癒效果而聞名，例如：促進血液循環、改善關節疼痛，甚至對一些皮膚問題有輔助療效，所以又被譽為「美人湯」。若想讓肌膚變得更加光滑細緻，不妨來萬座泡泡溫泉吧！', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/09-214019.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/09-214022.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/09-214023.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/29-212860.webp"]'::jsonb, E'2024-11-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23059', E'zh-Hant', 10, E'【2026】高崎達摩市集將於1月1日、2日舉行！介紹群馬傳統活動的魅力與亮點', E'高崎達摩市集是群馬縣高崎市引以為傲的新年傳統活動。2026年將於1月1日和2日在高崎站西口站前大道舉行，本文將全面介紹高崎達摩市集的亮點、概要、交通方式以及交通管制情況。\n\n高崎達摩市集是販售高崎達摩、提供高崎美食以及舉行舞台活動的活動。因為2026年此活動將於元旦至1月2日舉行，成為全日本最早的達摩市之一。\n\n除了經典的紅色達摩之外，還有其他各式各樣的達摩，包括以十二生肖為主題設計的達摩，讓人目不暇接。\n\n以下分別從「高崎達摩販售」、「開運高崎食堂」以及「舞台活動」三個特色進行介紹。在眾多亮點中尋找最適合自己喜歡的部分來享受吧！', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/04-213603.webp"]'::jsonb, E'2024-12-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7216', E'zh-Hant', 11, E'【2026】不想在東京賞櫻人擠人！「埼玉」超狂櫻花隧道10選', E'鄰近東京都的埼玉縣，擁有豐富的自然美景，從東京都心出發交通便利，「幸手權現堂堤」、「熊谷櫻堤」、「西武遊園地」、「川越」等埼玉縣內多處賞櫻名所都是佔地甚廣，櫻花數量都是上百株起跳，是東京都內見不到的磅礡氣勢。\n\n櫻花季時，東京都內總擠滿追櫻人潮。若想避開擁擠人群，又想同時被上百株櫻花感動，也希望能當日往返東京都內的話，就不妨來鄰近東京近郊的埼玉縣賞櫻吧！\n\n從東京搭電車約1小時即可到達的埼玉縣，其往年的賞櫻時期大約是3月下旬～4月中旬。以下將介紹埼玉縣內10處賞櫻景點，交通便利、感動美景的願望，一次滿足！\n\n位於埼玉縣的幸手是關東數一數二知名的賞花景點，千棵櫻花樹綿延成1公里的櫻堤，一旁是整片的油菜花田，兩者同時盛開時，粉嫩的春色豪邁潑灑在這片河堤上，熱鬧繽紛。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/03/21-73519.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/21-73520.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/21-73509.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/21-73507.webp"]'::jsonb, E'2019-03-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24037', E'zh-Hant', 11, E'【2026】埼玉縣賞櫻名所7選！幸手權現堂、長瀞等推薦賞花景點', E'埼玉縣擁有眾多賞花景點。正在猶豫該去哪裡欣賞櫻花的朋友，是否感到難以抉擇呢？本篇文章將為您介紹埼玉縣特別推薦的7大賞櫻景點。想要在埼玉欣賞櫻花的人，歡迎參考這篇指南喔！\n\n埼玉縣位於關東地區的內陸地區。西部是秩父山地，東部則是一片關東平原，擁有豐富的自然風光。\n\n每到春天，埼玉縣各地都有許多美麗的賞櫻景點。不論是居住在埼玉縣的居民，還是從縣外遠道而來的遊客，了解這些賞櫻名所都非常有價值。\n\n我們整理了每個景點的最佳觀賞時節、櫻花種類及其特色，供您參考，幫助您規劃花見行程。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/11-223785.webp","https://resources.matcha-jp.com/resize/720x2000/2025/12/26-254093.webp"]'::jsonb, E'2025-03-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24013', E'zh-Hant', 11, E'【2026】小江戶川越賞櫻看這篇就好！推薦川越的7大賞櫻景點', E'埼玉縣川越市有許多可以欣賞櫻花的絕景景點。在本文中，我們將為您介紹其中特別推薦的7個賞花景點。這些地方都是能讓您欣賞到美麗櫻花的好去處。如果您計劃在川越賞櫻，請務必參考這篇文章哦！\n\n川越是位於埼玉縣西部的一座城市。在江戶時代曾作為城下町繁榮一時，至今仍保留著許多古老的建築物。\n\n在充滿懷舊氛圍的川越，也有多處可以欣賞櫻花的景點。此外，每年從3月底到5月初還會舉辦「小江戶川越春祭」，屆時可以享受更加熱鬧的春季活動體驗。\n\n本文精選了川越賞櫻的7個推薦景點，為您詳細介紹各地的特色以及櫻花的最佳賞花期。對此感興趣的讀者，請務必參考後前往欣賞這些美麗的櫻花景點！', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/09-223463.webp","https://resources.matcha-jp.com/resize/720x2000/2025/12/26-254093.webp"]'::jsonb, E'2025-03-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23738', E'zh-Hant', 12, E'【2026】千葉縣賞櫻就來這裡！10大知名景點和秘境總整理', E'千葉縣各地區都有許多賞櫻名勝和秘境景點。本文將為您介紹其中特別推薦的10個地點。這些地方都有美麗的櫻花，非常適合賞花。想在千葉縣欣賞櫻花的朋友，請參考以下內容。\n\n在這樣的千葉縣，春天也有多處可以欣賞美麗櫻花的景點。此外，還有些地方可以同時欣賞櫻花和油菜花。\n\n種植的櫻花品種包括染井吉野、河津櫻、楊光等，總數多達1,000棵。因此被稱為「新川千本櫻」。\n\n新川的櫻花最佳觀賞期通常在2月中旬到3月中旬。由於也種植了較早開花的河津櫻，因此可以長時間欣賞櫻花。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/24-220946.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/26-221040.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/24-220948.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/24-220949.webp"]'::jsonb, E'2025-01-30'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/9680', E'zh-Hant', 12, E'【千葉】「櫻木神社」櫻花御朱印攻略：季節限定款、領取流程與必買朱印帳', E'櫻木神社位於千葉野田市，為當地最古老神社，境內櫻花繁盛，每年3月推出受歡迎的櫻花限定御朱印，吸引關東各地御朱印迷前來朝聖。文章說明限定款式與和紙印章特色、領取號碼牌與排隊流程，以及現場可順便購買的櫻花主題御守與華麗朱印帳，並提醒參觀時可參拜結良緣的櫻花樹、體驗神社特色小景點。\n\n日本櫻花季不只四處追櫻，御朱印迷們也四處收集紙上的櫻浪慢。今天要介紹千葉縣野田市的櫻木神社，每年推出的櫻花限定御朱印，是關東地區相當受歡迎的御朱印，吸引許多御朱印迷不遠千里而來。就讓小編分享一下入手的心得吧！\n\n位於千葉縣野田市的「櫻木神社」是市內最古老的神社，已有千年歷史。神社名稱源自祭祀著的櫻木。據說一開始是在一棵又大又美的櫻花樹下，祭祀和富貴、財運、食物相關的稻靈「倉稻魂命」。根據神社的網頁，櫻花的日文「さくら」剛好可解釋為「稻靈鎮座的場所」，\n\n之後神社也祭祀開運、勝運之神「武甕槌命」，以及夫婦神「伊弉諾尊」和「伊弉冉尊」，因此也可在這兒祈求良緣。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/14-101336.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/14-101331.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/14-101324.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/14-101334.webp"]'::jsonb, E'2020-04-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6979', E'zh-Hant', 12, E'冬天也能不流鼻水輕鬆玩！東京迪士尼穿搭指南', E'東京迪士尼樂園一年四季都好玩！但是服裝穿搭總是讓許多旅人煩惱，尤其要帶小孩到迪士尼樂園遊玩的爸媽，千萬不可輕忽！靠海的迪士尼樂園、迪士尼海洋，到了冬季常刮起大風、氣溫驟降。如何穿得保暖又能輕鬆在樂園裡走動遊玩？就讓常跑迪士尼的MATCHA小編告訴你！\n\n東京迪士尼因為地理位置的關係，體感溫度比其他地區再冷一些，加上不管在迪士尼樂園或是迪士尼海洋，室內的設施不算多。若長時間都在室外移動，一定要準備帽子、手套、圍巾等禦寒配件，最好也攜帶幾個暖暖包放在口袋，以防不時之需。尤其是看遊行、表演秀、排隊的時候，身體在非走動的情況下，如果穿得不夠保暖，就如赤裸站在冷風中般，宛如身置冰雪奇緣的世界！ 另外，也建議選擇行動方便的大容量背包（大家都知道，迪士尼超好買，不買幾樣伴手禮真的會後悔啊！）如果在園區內提著大包小包的移動、玩設施，很容易掉東掉西，所以還是大容量背包最實用。\n\n以上整理了冬季迪士尼的穿搭推薦，不論是迪士尼樂園或是海洋在特定期間內都會舉辦許多有趣活動，只是還是要提醒大家一定不要輕忽迪士尼的低溫與冷風，穿得保暖又輕便才能玩得盡興喔！ 小編推薦延伸閱讀 日本夏季特殊風景？觀察日本人夏天的「奇怪」現象\n\n想更了解日本、了解日本文化，就讓MATCHA透過有趣的漫畫方式來替你解答！像是「關東人與關西人哪裡不同？」、「到日本旅遊後難以習慣的事情」⋯等，透過輕鬆有趣的漫畫小短篇讓喜歡日本的你更了解日本～★', E'["https://resources.matcha-jp.com/resize/720x2000/2019/01/16-69466.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/16-69465.webp"]'::jsonb, E'2019-01-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/65', E'zh-Hant', 13, E'抹茶控的最愛！嚴選16款東京抹茶甜點和零食', E'在出門旅行之際，想必有許多人都會為家人和朋友選購伴手禮吧。但是伴手禮的種類多樣，有的時候也不知道該買什麼呢。本篇文章嚴選了16款在日本十分有人氣的抹茶甜品和零食，十分適合作為伴手禮帶回家。\n\n來日本旅行時，想必有許多人都會為家人和朋友選購伴手禮吧！但是伴手禮種類多樣，有時候實在不知道該從哪裡下手。\n\n本篇文章將為大家排憂解惑，小編這次特別挑選了在日本十分有人氣的抹茶甜品和零食，讓大家作為伴手禮帶回家。抹茶是一種茶，作為一種甜品口味，十分具有人氣。\n\n而抹茶魅力之處，在於可以透過甜點和零食輕鬆品嘗到傳統飲品的味道，且抹茶口味的零食色彩都很漂亮。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/02/16-48310.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/07-53420.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/16-48303.webp","https://resources.matcha-jp.com/resize/720x2000/2026/01/20-256269.webp"]'::jsonb, E'2018-10-02'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/204', E'zh-Hant', 13, E'神樂坂', E'神樂坂（日語：神楽坂／かぐらざか，羅馬化：Kagurazaka）是日本東京都新宿區的一個地區，也是早稻田通從大久保通到外堀通之間長一公里的坂（坡道）。\n\n大久保通的一端稱為「坂上」、外堀通的一端稱為「坂下」。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/09/20-129921.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/04-57704.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/04-57700.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/04-57703.webp"]'::jsonb, E'2018-11-12'::timestamptz, E'神樂坂', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E7%A5%9E%E6%A8%82%E5%9D%82'),
(E'https://matcha-jp.com/tw/27358', E'zh-Hant', 13, E'東京旅行絕不可錯過！GINZA SIX 獨家「限定伴手禮」與「美食體驗」完全指南', E'匯聚世界頂級精品品牌、當代藝術與美食的「GINZA SIX」，是銀座最具代表性的時尚地標。本文將帶你探索 GINZA SIX 獨有的魅力，從精緻伴手禮、名店美食到優雅的下午茶時光，感受銀座充滿品味的生活風景。\n\n說到銀座購物和逛街，「GINZA SIX」可以說是最具代表性的銀座象徵地標，這裡集結全球頂級奢侈品牌、美妝、當代藝術、精緻美食和甜點。\n\n建築為地下 6 層、地上 13 層的複合式商業設施，其中 9 個商業樓層匯集了約 240 家品牌店家進駐。而地下 3 樓則設有可以觀賞日本傳統藝能「能劇」的「觀世能樂堂」，在購物之餘，也能親身體驗日本傳統文化。\n\n除了匯聚超過 30 間以上的頂級餐廳、咖啡廳和酒吧之外，地下二樓的伴手禮區大家一定會逛到不想離開！', E'["https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266419.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266420.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266421.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266422.webp"]'::jsonb, E'2026-07-04'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3691', E'zh-Hant', 14, E'【2026最新】鎌倉賞櫻景點10選（高德院，長谷寺，鶴岡八幡宮，建長寺）', E'從東京出發到鎌倉也只需要1小時，非常方便，一整年都會有許多觀光客造訪。往年鎌倉約於4月初左右滿開。這次小編就要來介紹我們推薦的鎌倉賞櫻景點如高德院,長谷寺,鶴岡八幡宮等景點以及賞花時的基本資訊。\n\n鎌倉位於神奈川縣的南邊，這邊有許多富含魅力的觀光地，像是可以感受到日本傳統的建築物或遺跡等，以及四季皆宜的自然風景。從東京前往鎌倉也僅需要1個鐘頭，交通非常方便，整年都有許多來自國內外的觀光客來訪。\n\n鎌倉一到春天，賞櫻可說是可享當地醍醐味的活動。這邊的賞櫻最佳季節為3月下旬〜4月上旬，主要開的花種為染井吉野。也有比較早開花的品種，像是河津櫻等，從2月左右到4月都可能看得到，也就是說在鎌倉可以賞花的季節就相對增加了。\n\n鎌倉是一個有許多寺社佛閣及傳統街景的地方，以這些街道為背景賞花實在是太吸引人了，為此我們要來介紹一下10個很棒的賞櫻景點。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/12/21-68389.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/21-68398.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/21-68392.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/21-68393.webp"]'::jsonb, E'2017-03-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24126', E'zh-Hant', 14, E'【2026】小田原賞櫻・花見名所10選！開花預測與私房景點一併介紹', E'我們詳細整理了小田原的賞櫻名所，以及能悠閒度過時光的私房景點。隨著春天的到來，小田原處處盛開著美麗的櫻花。想與家人或朋友一同享受賞花樂趣的您，快來看看吧！\n\n小田原有以小田原城為首的知名賞櫻景點，當然也有可以悠閒享受賞花樂趣的私房景點散落其中。\n\n本文將為您介紹小田原的10個賞櫻名所，包括櫻花盛開的最佳時期以及避開人潮的隱藏景點。\n\n小田原城址公園護城河與櫻花攜景 Picture courtesy of 神奈川縣小田原市 依創作共用授權條款 CC 4.0 License 小田原城址公園的櫻花由約300棵染井吉野櫻構成，與歷史悠久的天守閣相輝映，景色格外迷人。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/16-224625.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/16-224627.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/16-224630.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/16-224629.webp"]'::jsonb, E'2025-03-31'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23636', E'zh-Hant', 14, E'【2026】橫濱賞櫻名所10選：開花預測時期及秘境景點介紹', E'為您精選橫濱10大賞櫻景點！本文將全面介紹開花預測時間、最適合賞櫻的知名景點、秘境以及各處的亮點。我們還列出了適合家庭出遊和約會的地點！有些地方還會舉辦夜櫻活動和櫻花節，千萬別錯過。希望這篇文章能為您規劃橫濱春季賞櫻之旅提供參考。\n\n這次我們將介紹橫濱花見景點的經典和隱藏地點，當然還有預計開花時間、夜櫻和櫻花節的資訊！\n\n園內分布著重要文化財建築，櫻花與歷史建築的和諧是其魅力所在。春天約有250棵櫻花盛開。\n\n預計開花時間通常在3月上旬到4月中旬。白天賞花當然很棒，但夜晚點燈的夜櫻和山丘上的三重塔別有一番風味，非常適合女子會或大人約會！', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/19-219865.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/27-221190.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/27-221191.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/19-219866.webp"]'::jsonb, E'2025-02-04'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/25331', E'zh-Hant', 15, E'【關東紅葉】涼爽秋季旅行季到來！關東地區賞楓必遊景點', E'隨著秋天的來臨，關東近郊的山岳與公園也被繽紛的紅葉妝點得美不勝收。特別是在10月，紅黃交錯的樹葉正值最佳觀賞期，吸引了眾多遊客前來欣賞大自然鮮明的色彩。\n\n在日本，秋天的山巒和行道樹都會染上紅葉，自古以來就有「賞楓」的習俗。除了春天賞櫻之外，賞楓也是感受四季變遷的重要文化。尤其是在10月到11月，楓樹和銀杏樹染上美麗的色彩，許多人都會前往著名的紅葉勝地，沉浸在大自然的美景中。這些地方同時也會成為國內外遊客熱門的旅行地點，在此期間寺廟、神社、公園和山區經常會舉辦燈飾或是各種活動，吸引遊客來訪。\n\n秋天的紅葉不僅是一種季節變換、美麗的景色，也是日本人「品味秋天」的重要季節象徵。\n\n「紅葉(KOYO)」是指秋季樹葉變紅變黃的自然現象。這個詞通常用來指稱各種樹木的顏色，不僅包括楓樹，還包括銀杏樹、橡樹和山毛櫸樹。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238244.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238115.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238116.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238117.webp"]'::jsonb, E'2025-07-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/22718', E'zh-Hant', 15, E'【新潟】越後湯澤滑雪場11選！夜間滑雪・初學者推薦！', E'為您介紹從關東地區出發交通便利的湯澤滑雪場11選。湯澤擁有多樣特色的滑雪場，無論是親子同遊、初學者體驗，還是提供夜間滑雪，都能找到適合自己的選擇。請參考本篇文章，讓您的滑雪季更盡興！\n\n新潟縣湯澤町擁有關越自動車道的湯澤交流道以及上越新幹線的越後湯澤站，是一個從關東地區出發交通便利的地區。\n\n湯澤以雪質優良聞名，吸引了眾多滑雪客前來。此外，多數滑雪場提供優惠的纜車票，也是其特點之一。在本文中將介紹其中最推薦的11座滑雪場。\n\n這些滑雪場不僅夏季也可享受樂趣，還能體驗眾多豐富的滑雪道，甚至還有可透過直播攝影機掌握雪道狀況的滑雪場。本次精選了7座特色滑雪場供您參考。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209946.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209947.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209950.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209966.webp"]'::jsonb, E'2025-03-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23687', E'zh-Hant', 15, E'新潟市區一日遊推薦路線！漫步享受日本酒、越光米、古物商店街', E'雪國「新潟」由於水質清澈甘醇，因此盛產舉世聞名的越光米與清酒。本次小編將用一天的時間，來品嚐飯糰、日本酒、拉麵等美食，還要前往沼垂露臺商店街挖掘古物，登上31樓高的Befco bakauke展望室欣賞無邊際夕陽美景！\n\n從新潟站走15分鐘便是到垂沼地區，而今代司酒藏在這一帶歷史悠久（1767年創業），能參觀他們的酒廠是一個不錯的體驗。他們有提供英語導覽團，讓外國遊客都可以了解日本酒的釀造過程與歷史。星期一至五，每天下午2時都有一團英語導覽團，就算你的時間無法配合，其他時間的導覽團，也有提供英文小冊子，讓旅客可以一邊確認資訊一邊觀賞。\n\n店內有設置收費與免費的試酒專區，想品嚐看看特別的日本酒，可以多付1000日圓到特別區域試酒。此外，賣店販售多款日本酒，部份品項更是此店限定，還有提供一些非酒精飲品的記念品，也是個購買伴手禮的好地方。\n\n原為市場的長屋改裝而成，從前是因船泊來的商業交易市場，繁榮盛極一時。後來繁華的景象慢慢消逝，不過現在仍殘留昭和時代的氛圍。因此，這裡的人嘗試活化長屋，希望注入新的活力，從2010年開始陸續有個性商店進駐，每家店都很有自己的特色，走的是文創、文青路線。這裡平日的人比較少，假日則有時會舉行市集。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/19-219834.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/19-219835.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/19-219836.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/19-219837.webp"]'::jsonb, E'2025-01-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/9810', E'zh-Hant', 16, E'【富山美食】就是要夠黑才夠味！富山站附近黑拉麵2選', E'說到日本「富山」除了有聞名全日本的海產海鮮之外，其實富山還有另一種深受歡迎的庶民小吃「黑拉麵」，當地人甚至認為：沒有吃過黑拉麵便等於沒來過富山！本篇介紹兩家在地人推薦的黑拉麵料理店，不論是元祖或是冠軍，都以獨門醬汁煮出特別湯頭，還能吃到當地才有的白蝦天婦羅。喜歡拉麵的你，來到富山一定要試試這碗不一樣的料理！\n\n日本富山因為有著富山灣，海產特別豐富，「富山灣壽司」聞名全日本。無論是本地還是外國的觀光客，來到富山總是會吃這裡知名的壽司。除了壽司，富山還有另一種人氣美食「富山黑拉麵」，當地人說沒有吃過黑拉麵等於沒來過富山。這次讓小編介紹兩間在富山車站附近的黑拉麵店，除了方便以外，更是當地人的推薦店家。\n\n富山黑拉麵湯頭加入店家秘製的黑醬油，而呈現令人印象深刻的外觀。說起富山黑拉麵的由來，源於從前富山一帶有許多勞動人口，他們的日常工作都會大量出汗，流失鹽份很多，因此他們需要在短短的午餐時間內快速補充鹽份，拉麵含澱粉質、豬骨湯頭含蛋白質，再加上大量鹽份，讓工人可以一次補充能量。\n\n普遍來說，富山黑拉麵湯麵條比較粗也帶有嚼勁，染上了淺棕色的麵條，帶股鹹味，或許不是每個人都能接受這樣的重口味，但既然是當地名產，就跟著富山人體驗一次吧！', E'["https://resources.matcha-jp.com/resize/720x2000/2020/05/20-103080.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/20-103073.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/20-103077.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/20-103084.webp"]'::jsonb, E'2020-05-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7212', E'zh-Hant', 16, E'【昇龍道】名古屋出發！七天範例行程走訪人氣與私房景點', E'從名古屋中部機場出發，如何玩遍昇龍道，一路北上暢遊岐阜、富山、金澤、福井等人氣觀光地，盡情享用美食，最後不忘在名古屋購物的示範七天行程整理給大家！\n\nMATCHA將為各位介紹從名古屋進出，以順時針玩遍岐阜、富山、石川、福井等四縣的七天六夜行程、熱門景點等，打算前往北陸自由行的朋友們不妨參考看看。 KKday預約「黑部立山雪牆絕景三日遊」\n\n日本中部北陸地區的地形加上能登半島的形狀有如龍頭，讓人想起龍乘風向天高昇的英姿，因此這個觀光區被稱為「昇龍道」。\n\n昇龍道由南到北橫跨中部地方的愛知縣、岐阜縣、富山縣、石川縣，擁有許多的溫泉、美麗的自然環境，更因愛知縣岡崎市是江戶幕府建立者德川家康的出生地，昇龍道保有許多以德川家康為首的文化建築、祭典等，可說是一條能夠盡享各種不同日本魅力的觀光路線。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/07/18-31446.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/02-53314.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/03-74223.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/31-34865.webp"]'::jsonb, E'2019-04-01'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24042', E'zh-Hant', 16, E'【2026】富山縣櫻花名所7選！感受北陸春天的氣息', E'富山縣有許多賞櫻的名所，但有些人可能會不知道該去哪裡賞櫻吧？本篇文章將為您介紹富山縣內7個精選的櫻花名所。不論是富山縣內居民，還是來自其他地區的旅客，都請務必參考看看哦！\n\n富山縣位於本州的中央北部地區，面向日本海，因為四周群山圍繞，擁有豐富的自然環境。\n\n到了春天，富山縣就會出現許多美麗的賞櫻景點。如果您住在富山縣，或者計劃在春季到訪富山，想必會對這裡的櫻花名所感到好奇吧？\n\n我們也會詳細介紹各景點的特色、櫻花的花期及種類等資訊，提供您作為參考，幫助您規劃愉快的賞櫻行程！', E'["https://resources.matcha-jp.com/resize/720x2000/2025/12/26-254093.webp"]'::jsonb, E'2025-03-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7545', E'zh-Hant', 17, E'能登半島', E'能登半島（日語：能登半島／のとはんとう，羅馬化：Noto hantō）是位於日本北陸地方中央附近，向日本海往北延伸出去的半島。\n\n整個區域都屬於石川縣，在中途往東彎曲形成了富山灣。半島內大多為標高200～500公尺的丘陵地帶，少有平地。58平方公里。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/12-79333.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/14-79528.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/06-100898.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/12-79309.webp"]'::jsonb, E'2019-08-18'::timestamptz, E'能登半島', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E8%83%BD%E7%99%BB%E5%8D%8A%E5%B3%B6')
